package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ExpectedEveryMinutesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property expected every minutes of observed source ")
  void test_expected_every_minutes_v_o_builder() {
    Assertions.assertFalse(ExpectedEveryMinutesVO.nullValue().getExpectedEveryMinutes().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        ExpectedEveryMinutesVO.tryFrom(null).getExpectedEveryMinutes().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1,
        ExpectedEveryMinutesVO.from(1).getExpectedEveryMinutes().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ExpectedEveryMinutesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ExpectedEveryMinutesVO.from(1).toString());
  }
}
